// src/auth-pages.ts - Browser routing utilities
export function arcTabScript(bundleId string, url: string): string {
  const escapedUrl = url.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
  return `
tell application id "${bundleId}"
    activate
    if (count of windows) is 0 then
        make new window
    end if
 tell front window to make new tab with properties {URL:"${escapedUrl}"}
end tell
  `.trim();
}

export function isArcBundle(bundleId: string): boolean {
  const lower = bundleId.toLowerCase();
  return lower === 'company.thebrowser.browser' || 
         lower === 'company thebrowser.dia';
}
