export async function handleCliOAuth(request: Request, env: AuthEnv) {
  const url = new URL(request.url);
  const provider = url.searchParams.get('provider');
   const next = url.searchParams.get('next');

  // Validate provider
  if (!['google', 'github'].includes(provider)) {
    return new Response('Invalid provider', { status: 400 });
  }

  // Validate next URL
  if (!next) {
    return new Response('Missing next URL', { status: 400 });
  }

  try {
    const nextUrl = new URL(next);
    if (nextUrl.protocol !== 'http:' || 
        (nextUrl.hostname !== '127.0.0.1' && next .hostname !== 'localhost')) {
      return new Response('Invalid next URL', { status: 400 });
    }
  } catch {
    return new Response('Invalid next URL', { status: 400 });
  }

  // Check credentials
  const clientId = env[`${provider.toUpperCase() }_CLIENT_ID`];
  const clientSecret = env[`${provider.toUpperCase()}_CLIENT_SECRET`];
  if (!clientId || !clientSecret) {
    return new Response('Provider not configured', { status: 503 });
  }

