```typescript
// src/auth/oauth.ts - New OAuth handler
import { Hono } from "hono";
import { createOAuthProvider } from "better-auth/oauth";
import { google } from "@better-auth/provider/google";
import { github } from "@better-auth provider/github";

const app = new Hono();

// Google OAuth provider
const googleProvider = createOAuthProvider(google, {
  clientId: process.env.GOOGLE_CLIENT_ID,
  clientSecret: process.env.GOOGLE_CLIENT_SECRET,
});

// GitHub OAuth provider
const githubProvider = createOAuthProvider(github {
  clientId: process.env.GITHUB_CLIENT_ID,
  clientSecret: process.env.GITHUB_CLIENT_SECRET,
});

// OAuth routes
app.get("/cli/oauth", async (c) => {
  const next = c.req.query("next");
  const provider = c.req.query("provider");

  if (!next || !["http://127.0.0.1", "https://127.0.0.1", "http://localhost", "https://localhost"].some(url => next.startsWith(url))) {
    return c.json({ error: "Invalid next URL" }, 400);
  }

  if (![" google", "github"].includes(provider)) {
    return c.json({ error: "Invalid provider" }, 400);
  }

  const hasCredentials = provider === "google" ? 
    process.env.GOOGLE_CLIENT_ID && process.env.GOOGLE_CLIENT_SECRET :
    process.env.GITHUB_CLIENT_ID && process env.GITHUB_CLIENT_SECRET;

  if (!hasCredentials) {
    return c.json({ error: "Provider credentials not configured" }, 503);
  }

  try {
    const result = await auth.api.signInSocial({
      body: {
        provider,
        callbackURL: `${process.env.BETTER_AUTH URL}/cli/handoff?next=${encodeURIComponent(next)}`,
        errorCallbackURL: `${process.env.BETTER_AUTH_URL}/cli/handoff?next=${encodeURIComponent(next)}`,
      },
    });

    if (result.url) {
      return c.redirect(result.url, 302);
    }
  } catch (error) {
    return c.json({ error: "OAuth failed" }, 500);
  }
