}

export function handoffRedirectPage(target: string): string {
  const escaped = escapeHtml(target);
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex">
<meta name="referrer" content="no-referrer">
<meta http-equiv="refresh" content="0;url=${escaped}">
<title>Tui — Returning to the CLI</title>
<style>${STYLE}</style>
</head>
<body>
<main class="card" data-tone="ok">
<span class="badge">${CHECK_ICON}</span>
<p class="eyebrow">Tui</p>
<h1>Returning to the CLI</h1>
<p class="lead">Handing your session back to Tui. You can close this tab once it finishes.</p>
<script>location.replace(${JSON.stringify(target)});</script>
</main>
</body>
</html>`;
}

export function unsignedInPage(): string {
  return arcadePage(
    "warn",
    "You're not signed in",
    "The browser doesn't have a Tui session to hand back to the CLI.",
    [
      "Start from the terminal with <code>gamepigeon auth oauth google</code> or <code>gamepigeon auth oauth github</code>.",
      "Finish signing in in this browser, then try again.",
    ],
    "Prefer email and password? <code>gamepigeon auth login</code> signs in the same account.",
  );
}

