export interface OAuthCallbackServer {
  readonly port: number;
  ready: Promise<void>;
  token: Promise<string>;
  close(): void;
}

function isAddrInUse(error: unknown): boolean {
  return Boolean(error && typeof error === "object" && "code" in error && (error as { code?: string }).code === "EADDRINUSE");
}

function queryParam(query: string, key: string): string | undefined {
  for (const pair of query.split(/[&?]/)) {
    const cut = pair.indexOf("=");
    if (cut === -1) continue;
    if (pair.slice(0, cut) === key) return pair.slice(cut + 1).replace(/\+/g, " ");
  }
  return undefined;
}

function percentDecode(value: string): string {
  try {
    return decodeURIComponent(value);
  } catch {
    return value;
  }
}

function callbackFailure(query: string): string | undefined {
  const error = queryParam(query, "error");
  if (!error) return undefined;
  if (error === "access_denied") return "Sign-in was cancelled before it finished.";
  const description = queryParam(query, "error_description");
  if (description) return percentDecode(description);
  return `The login page reported an error: ${percentDecode(error)}`;
}

function listenOn(server: Server, port: number): Promise<number> {
  return new Promise((resolve, reject) => {
    const onError = (error: Error) => {
      server.off("listening", onListening);
      reject(error);
    };
    const onListening = () => {
      server.off("error", onError);
      const address = server.address();
      if (address && typeof address === "object") resolve(address.port);
      else reject(new Error("Could not start the sign-in listener."));
    };
    server.once("error", onError);
    server.once("listening", onListening);
    server.listen(port, "127.0.0.1");
  });
}

export function startOAuthCallbackServer(port: number): OAuthCallbackServer {
  let boundPort = port;
  const server = createServer((request, response) => {
    const target = request.url ?? "/";
    const cut = target.indexOf("?");
    const path = cut === -1 ? target : target.slice(0, cut);
    const query = cut === -1 ? "" : target.slice(cut + 1);

    const reply = (status: number, contentType: string, body: string, extra: Record<string, string> = {}) => {
      response.writeHead(status, {
        "Content-Type": contentType,
        "Content-Length": Buffer.byteLength(body),
        Connection: "close",
        ...extra,
      });
      response.end(body);
    };

    if (request.method === "GET" && path === "/auth/ping") {
      reply(200, "text/plain; charset=utf-8", "ok");
      return;
    }

    if (path !== "/auth/callback") {
      reply(404, "text/plain; charset=utf-8", "not found");
      return;
    }

    const headers = {
      "Cache-Control": "no-store",
      "Referrer-Policy": "no-referrer",
    };
    const reason = callbackFailure(query);
    if (reason) {
      reply(400, "text/html; charset=utf-8", signInFailedPage(escapeHtml(reason)), headers);
      failToken(new Error(reason));
      return;
    }
    const tokenValue = queryParam(query, "token");
    if (!tokenValue) {
      const missing = "The login page came back without a session token.";
      reply(400, "text/html; charset=utf-8", signInFailedPage(escapeHtml(missing)), headers);
      failToken(new Error(missing));
      return;
    }
    reply(200, "text/html; charset=utf-8", signedInPage(), headers);
    fulfillToken(tokenValue);
  });

  let settled = false;
  let fulfillToken = (_value: string) => {};
  let failToken = (_error: Error) => {};
  const token = new Promise<string>((resolve, reject) => {
    fulfillToken = (value) => {
      if (settled) return;
      settled = true;
      resolve(value);
    };
    failToken = (error) => {
      if (settled) return;
      settled = true;
      reject(error);
    };
  });
  token.catch(() => {});

  const ready = (async () => {
    try {
      boundPort = await listenOn(server, port);
    } catch (error) {
      if (!isAddrInUse(error)) throw error;
      boundPort = await listenOn(server, 0);
    }
  })();

  return {
    get port() {
      return boundPort;
    },
    ready,
    token,
    close() {
      server.close();
    },
  };
}

function applescriptEscape(value: string): string {
  return value.replaceAll("\\", "\\\\").replaceAll('"', '\\"');
}

export function isArcBundle(bundleId: string): boolean {
  const id = bundleId.toLowerCase();
  return id === "company.thebrowser.browser" || id === "company.thebrowser.dia";
}

export function arcTabScript(bundleId: string, url: string): string {
  return `tell application id "${applescriptEscape(bundleId)}"
    activate
    if (count of windows) is 0 then
        make new window
    end if
    tell front window to make new tab with properties {URL:"${applescriptEscape(url)}"}
end tell`;
}

function parseDefaultHttpsHandler(plist: string): string | undefined {
  for (const block of plist.split("{")) {
    if (!block.includes("LSHandlerURLScheme = https;")) continue;
    const line = block.split("\n").find((entry) => entry.trimStart().startsWith("LSHandlerRoleAll = "));
    if (!line) continue;
    let value = line.trim().slice("LSHandlerRoleAll = ".length);
    if (value.endsWith(";")) value = value.slice(0, -1);
    if (value.startsWith('"') && value.endsWith('"')) value = value.slice(1, -1);
    if (value) return value;
  }
  return undefined;
}

function runOpener(command: string, args: string[]): boolean {
  const result = spawnSync(command, args, { stdio: "ignore" });
  return result.status === 0;
}

function defaultHttpsHandler(): string | undefined {
  const result = spawnSync(
    "defaults",
    ["read", "com.apple.LaunchServices/com.apple.launchservices.secure"],
    { encoding: "utf8" },
  );
  if (result.status !== 0 || !result.stdout) return undefined;
  return parseDefaultHttpsHandler(result.stdout);
}

function openBrowser(url: string): boolean {
  if (process.platform === "darwin") {
    const bundleId = defaultHttpsHandler();
    if (bundleId && isArcBundle(bundleId) && runOpener("osascript", ["-e", arcTabScript(bundleId, url)])) {
      return true;
    }
    return runOpener("open", [url]) || runOpener("open", ["-a", "Safari", url]);
  }
  if (process.platform === "win32") {
    return runOpener("cmd", ["/c", "start", "", url])
      || runOpener("rundll32", ["url.dll,FileProtocolHandler", url]);
  }
  return runOpener("xdg-open", [url])
    || runOpener("gio", ["open", url])
    || runOpener("x-www-browser", [url]);
}

async function signInWithOAuth(provider?: string): Promise<AuthSuccess> {
  if (provider !== "google" && provider !== "github") {
    throw new Error("usage: gamepigeon auth oauth [google|github]");
  }
  const callback = startOAuthCallbackServer(oauthCallbackPort);
  await callback.ready;
  const next = `http://127.0.0.1:${callback.port}/auth/callback`;
  const url = `${requireAuthBaseUrl()}/cli/oauth?provider=${provider}&next=${encodeURIComponent(next)}`;
  const opened = openBrowser(url);
  console.log(opened
    ? `Opening your browser to sign in with ${provider}...`
    : `Open this URL to sign in with ${provider}:\n${url}`);
  try {
    const sessionToken = await callback.token;
    const user = await resolveUser(sessionToken);
    saveSession(sessionToken, user);
    console.log(`Signed in as ${user.email}`);
    return { kind: "signed_in", method: provider, userId: user.id };
  } finally {
    callback.close();
  }
}

