import {
  createAuth,
  providerConfigured,
  trustedOrigins,
  type AuthEnv,
  type CliOAuthProvider,
} from "./auth";
import { handoffRedirectPage, unsignedInPage } from "./handoff-page";

const SESSION_COOKIE = "better-auth.session_token";
const NO_STORE = { "cache-control": "no-store", "referrer-policy": "no-referrer" };

function trustedCliNext(value: string | null): URL | null {
  if (!value) return null;
  try {
    const next = new URL(value);
    if (next.protocol !== "http:") return null;
    if (next.hostname !== "127.0.0.1" && next.hostname !== "localhost") return null;
    return next;
  } catch {
    return null;
  }
}

function cookieValue(header: string | null, name: string): string | null {
  if (!header) return null;
  for (const part of header.split(";")) {
    const trimmed = part.trim();
    const cut = trimmed.indexOf("=");
    if (cut === -1) continue;
    if (trimmed.slice(0, cut) !== name) continue;
    const value = trimmed.slice(cut + 1);
    return value || null;
  }
  return null;
}

function html(status: number, body: string): Response {
  return new Response(body, {
    status,
    headers: { "content-type": "text/html; charset=utf-8", ...NO_STORE },
  });
}

async function cliOAuth(url: URL, env: AuthEnv, request: Request): Promise<Response> {
  const provider = url.searchParams.get("provider");
  if (provider !== "google" && provider !== "github") {
    return Response.json({ error: "Unsupported provider" }, { status: 400 });
  }
  if (!providerConfigured(env, provider satisfies CliOAuthProvider)) {
    return Response.json({ error: `${provider} OAuth is not configured` }, { status: 503 });
  }
  const next = trustedCliNext(url.searchParams.get("next"));
  if (!next) {
    return Response.json({ error: "Invalid next URL" }, { status: 400 });
  }

  const handoff = new URL("/cli/handoff", env.BETTER_AUTH_URL);
  handoff.searchParams.set("next", next.toString());
  try {
    const result = await createAuth(env).api.signInSocial({
      body: {
        provider,
        callbackURL: handoff.toString(),
        disableRedirect: true,
      },
      headers: request.headers,
    });
    if (!result?.url) {
      return Response.json({ error: "Could not start sign-in" }, { status: 502 });
    }
    return Response.redirect(result.url, 302);
  } catch {
    return Response.json({ error: "Could not start sign-in" }, { status: 502 });
  }
}

async function cliHandoff(url: URL, env: AuthEnv, request: Request): Promise<Response> {
  const next = trustedCliNext(url.searchParams.get("next"));
  if (!next) {
    return Response.json({ error: "Invalid next URL" }, { status: 400 });
  }

  const auth = createAuth(env);
  const session = await auth.api.getSession({ headers: request.headers }).catch(() => null);
  const token = cookieValue(request.headers.get("cookie"), SESSION_COOKIE);
  if (!session?.user || !token) {
    return html(401, unsignedInPage());
  }

  next.searchParams.append("token", token);
  const target = next.toString();
  return html(200, handoffRedirectPage(target));
}

function authCors(request: Request, response: Response, env: AuthEnv): Response {
  const origin = request.headers.get("origin");
