test("startOAuthCallbackServer answers ping and saves a glued callback token", async () => {
  const callback = startOAuthCallbackServer(0);
  await callback.ready;
  try {
    const ping = await fetch(`http://127.0.0.1:${callback.port}/auth/ping`);
    expect(ping.status).toBe(200);
    expect(await ping.text()).toBe("ok");

    const response = await fetch(
      `http://127.0.0.1:${callback.port}/auth/callback?state=abc?token=session-secret`,
    );
    expect(response.status).toBe(200);
    expect(response.headers.get("cache-control")).toBe("no-store");
    expect(await response.text()).toContain("signed in");
    await expect(callback.token).resolves.toBe("session-secret");
  } finally {
    callback.close();
  }
});

test("startOAuthCallbackServer falls back when the requested port is busy", async () => {
  const blocker = createServer();
  await new Promise<void>((resolve, reject) => {
    blocker.once("error", reject);
    blocker.listen(0, "127.0.0.1", () => resolve());
  });
  const address = blocker.address();
  if (!address || typeof address !== "object") throw new Error("blocker did not bind");
  const busyPort = address.port;
  const callback = startOAuthCallbackServer(busyPort);
  try {
    await callback.ready;
    expect(callback.port).not.toBe(busyPort);
    expect(callback.port).toBeGreaterThan(0);
  } finally {
    callback.close();
    await new Promise<void>((resolve) => blocker.close(() => resolve()));
  }
});

