import { env } from "cloudflare:workers";
import { expect, test } from "vitest";
import worker from "../src/index";
import { handoffRedirectPage } from "../src/handoff-page";
import type { AuthEnv } from "../src/auth";

const authEnv = env as AuthEnv;

async function workerFetch(path: string, init?: RequestInit): Promise<Response> {
  return worker.fetch(new Request(`https://auth.example${path}`, init), authEnv);
}

test("GET /cli/oauth rejects unknown providers", async () => {
  const response = await workerFetch(
    "/cli/oauth?provider=twitter&next=http://127.0.0.1:3210/auth/callback",
  );
  expect(response.status).toBe(400);
});

test("GET /cli/oauth returns 503 when the provider has no credentials", async () => {
  const response = await workerFetch(
    "/cli/oauth?provider=google&next=http://127.0.0.1:3210/auth/callback",
  );
  expect(response.status).toBe(503);
});

test("GET /cli/oauth and /cli/handoff refuse a next target that is not loopback http", async () => {
  const rejected = [
    "https://127.0.0.1:3210/auth/callback",
    "http://example.com/auth/callback",
    "http://127.0.0.1.evil.test/auth/callback",
    "javascript:alert(1)",
    "/auth/callback",
  ];
  for (const next of rejected) {
    const handoff = await workerFetch(`/cli/handoff?next=${encodeURIComponent(next)}`);
    expect(handoff.status).toBe(400);

    const oauth = await workerFetch(
      `/cli/oauth?provider=google&next=${encodeURIComponent(next)}`,
    );
    expect(oauth.status === 400 || oauth.status === 503).toBe(true);
    if (oauth.status === 503) {
      // Unconfigured providers fail closed before starting sign-in; a missing
      // next still must not be treated as success.
      expect(oauth.status).not.toBe(200);
    }
  }
});

test("GET /cli/handoff answers 401 with oauth guidance when there is no session", async () => {
  const response = await workerFetch(
    "/cli/handoff?next=http://127.0.0.1:3210/auth/callback?state=abc",
  );
  expect(response.status).toBe(401);
  expect(response.headers.get("cache-control")).toBe("no-store");
  expect(await response.text()).toMatch(/oauth/i);
});

test("handoff page redirects with the literal target URL", () => {
  const target = "http://127.0.0.1:3210/auth/callback?state=abc&token=session-secret";
  const page = handoffRedirectPage(target);
  expect(page).toContain(target);
  expect(page).toContain("location.replace");
  expect(page).toContain(`url=${target.replaceAll("&", "&" + "amp;")}`);
});

