test("GET /cli/handoff appends the session cookie onto next and redirects", async () => {
  const secret = "migration-secret-for-cli-handoff";
  const configured = { ...authEnv, MIGRATION_SECRET: secret };
  const migrate = await worker.fetch(
    new Request("https://auth.example/migrate", {
      method: "POST",
      headers: { authorization: `Bearer ${secret}` },
    }),
    configured,
  );
  expect(migrate.ok).toBe(true);

  const signup = await worker.fetch(
    new Request("https://auth.example/api/auth/sign-up/email", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        email: "oauth-handoff@example.com",
        password: "password1234",
        name: "OAuth",
      }),
    }),
    configured,
  );
  const setCookie = signup.headers.get("set-cookie") ?? "";
  const match = /better-auth\.session_token=([^;]+)/.exec(setCookie);
  expect(signup.ok).toBe(true);
  expect(match?.[1]).toBeTruthy();
  const cookieToken = match![1]!;

  const next = "http://127.0.0.1:3210/auth/callback?state=abc";
  const response = await worker.fetch(
    new Request(`https://auth.example/cli/handoff?next=${encodeURIComponent(next)}`, {
      headers: { cookie: `better-auth.session_token=${cookieToken}` },
    }),
    configured,
  );
  expect(response.status).toBe(200);
  expect(response.headers.get("cache-control")).toBe("no-store");
  const body = await response.text();
  expect(body).toContain("location.replace");
  expect(body).toContain(`token=${cookieToken}`);
  expect(body).toContain("state=abc");
});

